//! What a `--clean-results` wipe of the MSL results directory removes, and what
//! it must leave behind.
//!
//! A results directory is regenerated by every run, so wiping it before a run is
//! the default. Two kinds of entry are exceptions, and both are exceptions for
//! the same reason: they carry state the next run *reads* rather than state the
//! next run rewrites.
//!
//! * `omc_parity_cache/` — the keyed OMC reference cache. Deleting it costs a
//!   full OMC re-run for no benefit.
//! * `msl_band_table.json` and `msl_band_table_previous.json` — the previous
//!   certification's per-model cohort evidence. The next run rotates the table
//!   aside and diffs against it to say which models entered or left the compared
//!   set. Wiping it makes every run a first certification: no diff, no
//!   departures, and a model can stop being compared with nothing on record.
//!
//! Preserving the table is safe because the table is self-describing: it carries
//! the content digest of the comparator output it was derived from, so a stale
//! one is *detected* by the harness rather than believed (see
//! `rumoca_test_msl::msl_tools::band_table::ensure_bound_to_dir`).

use std::ffi::OsStr;
use std::fs;
use std::path::Path;

const MSL_RESULTS_PRESERVED_DIRS: &[&str] = &["omc_parity_cache"];

/// Files a results-directory wipe must leave behind. See the module docs.
pub(super) const MSL_RESULTS_PRESERVED_FILES: &[&str] =
    &[BAND_TABLE_FILE, PREVIOUS_BAND_TABLE_FILE];

/// The band-table file names, spelled here rather than imported: `xtask`
/// deliberately links no compiler crates, and `rumoca-test-msl` (which owns
/// these names) pulls the whole stack in. The pair is pinned against its owner
/// by [`tests::msl_results_cleanup_preserves_the_band_table_names_the_harness_writes`].
const BAND_TABLE_FILE: &str = "msl_band_table.json";
const PREVIOUS_BAND_TABLE_FILE: &str = "msl_band_table_previous.json";

fn should_preserve_msl_results_entry(entry_path: &Path) -> bool {
    let Some(name) = entry_path.file_name().and_then(OsStr::to_str) else {
        return false;
    };
    if entry_path.is_dir() {
        return MSL_RESULTS_PRESERVED_DIRS.contains(&name);
    }
    MSL_RESULTS_PRESERVED_FILES.contains(&name)
}

/// Remove everything a run regenerates, keeping the preserved entries. Removes
/// the directory itself when nothing was preserved.
pub(super) fn clean_msl_results_dir(results_dir: &Path) -> std::io::Result<()> {
    if !results_dir.is_dir() {
        return Ok(());
    }

    for entry in fs::read_dir(results_dir)? {
        let entry = entry?;
        let path = entry.path();
        if should_preserve_msl_results_entry(&path) {
            continue;
        }
        if path.is_dir() {
            fs::remove_dir_all(&path)?;
        } else {
            fs::remove_file(&path)?;
        }
    }

    if fs::read_dir(results_dir)?.next().is_none() {
        fs::remove_dir(results_dir)?;
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::repo_root;

    #[test]
    fn a_stale_results_directory_is_removed_outright() {
        let temp = tempfile::tempdir().expect("tempdir");
        let results_dir = temp.path().join("results");
        fs::create_dir_all(&results_dir).expect("mkdir");
        fs::write(results_dir.join("stale.json"), "{}").expect("write stale file");

        clean_msl_results_dir(&results_dir).expect("cleanup should succeed");

        assert!(
            !results_dir.exists(),
            "a directory holding nothing preserved should be removed"
        );
    }

    #[test]
    fn the_keyed_omc_parity_cache_survives() {
        let temp = tempfile::tempdir().expect("tempdir");
        let results_dir = temp.path().join("results");
        let parity_cache_dir = results_dir.join("omc_parity_cache");
        fs::create_dir_all(&parity_cache_dir).expect("mkdir parity cache");
        fs::write(results_dir.join("stale.json"), "{}").expect("write stale file");
        fs::write(parity_cache_dir.join("compile.json"), "{}").expect("write cache file");

        clean_msl_results_dir(&results_dir).expect("cleanup should succeed");

        assert!(
            parity_cache_dir.join("compile.json").is_file(),
            "cleanup should preserve keyed OMC parity cache contents"
        );
        assert!(
            !results_dir.join("stale.json").exists(),
            "cleanup should remove stale non-cache artifacts"
        );
    }

    /// The band table is the previous certification's cohort evidence. Wiping it
    /// before every run makes every run a first certification: nothing to diff,
    /// so a model can leave the compared set with no record that it did.
    #[test]
    fn the_per_model_band_tables_survive() {
        let temp = tempfile::tempdir().expect("tempdir");
        let results_dir = temp.path().join("results");
        fs::create_dir_all(&results_dir).expect("mkdir results");
        fs::write(results_dir.join(BAND_TABLE_FILE), "{\"schema\":\"a\"}")
            .expect("write band table");
        fs::write(
            results_dir.join(PREVIOUS_BAND_TABLE_FILE),
            "{\"schema\":\"b\"}",
        )
        .expect("write previous band table");
        fs::write(results_dir.join("msl_results.json"), "{}").expect("write stale results");

        clean_msl_results_dir(&results_dir).expect("cleanup should succeed");

        assert_eq!(
            fs::read_to_string(results_dir.join(BAND_TABLE_FILE))
                .expect("the cohort table must survive a results wipe"),
            "{\"schema\":\"a\"}"
        );
        assert!(
            results_dir.join(PREVIOUS_BAND_TABLE_FILE).is_file(),
            "the rotated table must survive too; it is what the next diff reads"
        );
        assert!(
            !results_dir.join("msl_results.json").exists(),
            "everything the run regenerates must still be wiped"
        );
    }

    /// The preserved names are spelled in `xtask` (which links no compiler
    /// crates) and must not drift from the harness module that writes them.
    ///
    /// The pin reads the harness's **constant declarations**, not the file text:
    /// a substring search would keep passing if the names survived only in a
    /// comment, a doc example, or a variable that no longer names the file the
    /// harness writes.
    #[test]
    fn msl_results_cleanup_preserves_the_band_table_names_the_harness_writes() {
        let module = repo_root().join("crates/rumoca-test-msl/src/msl_tools/band_table.rs");
        let source = fs::read_to_string(&module).expect("read the band table module");
        let declared = |name: &str| -> String {
            let marker = format!("pub const {name}: &str = ");
            let start = source
                .find(&marker)
                .unwrap_or_else(|| panic!("{} declares no `{name}`", module.display()))
                + marker.len();
            let rest = &source[start..];
            let value_start = rest.find('"').expect("constant has no string literal") + 1;
            let value_end = value_start
                + rest[value_start..]
                    .find('"')
                    .expect("unterminated string literal");
            rest[value_start..value_end].to_string()
        };

        assert_eq!(
            declared("BAND_TABLE_FILE"),
            BAND_TABLE_FILE,
            "the harness writes a different current-table file name than the results wipe preserves"
        );
        assert_eq!(
            declared("PREVIOUS_BAND_TABLE_FILE"),
            PREVIOUS_BAND_TABLE_FILE,
            "the harness writes a different rotated-table file name than the results wipe preserves"
        );
        assert_eq!(
            MSL_RESULTS_PRESERVED_FILES,
            &[BAND_TABLE_FILE, PREVIOUS_BAND_TABLE_FILE],
            "both band-table files must be on the preserved list"
        );
    }
}
